import assert from 'node:assert/strict';
import {readdir,readFile,lstat,access} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import path from 'node:path';
import {existsSync} from 'node:fs';
import {maintainedCensus} from './audit-files.mjs';
import {dataDir,persist,load,startServer,createContext,child} from './acceptance-runtime.mjs';
const mode=process.argv[2];
const checks=[];
let server;
let error;
try{
  if(['smoke','restart','browser','remount'].includes(mode)){
    const ids=await load('acceptance-state.json');
    server=await startServer();
    const ctx=createContext(server.url,ids,checks,{readOnly:mode!=='smoke'});
    if(mode==='smoke'){
      const email=`acceptance-${Date.now()}@crew.test`;
      await ctx.check('signup/login and httpOnly session',async()=>{const user=await ctx.signup('owner',{name:'Acceptance Owner',email,password:'acceptance long password'});assert.equal(user.email,email);const me=await ctx.api('GET','/me');assert.equal(me.user.id,user.id);});
      for(const lane of ['people','work','insight']){
        const module=await import(new URL(`./checks/${lane}.mjs`,import.meta.url));
        await module.smoke(ctx);
      }
      await persist('acceptance-state.json',ids);
    }else if(mode==='restart'){
      assert.ok(ids.clients?.owner,'Existing smoke state is required');
      for(const lane of ['people','work','insight'])await(await import(new URL(`./checks/${lane}.mjs`,import.meta.url))).restart(ctx);
    }else if(mode==='browser'){
      await ctx.check('Chromium login, board drag, search and inbox',async()=>{
        const result=await child('/usr/bin/python3',['scripts/browser-smoke.py'],{env:{...process.env,CREW_BROWSER_URL:server.url,CREW_ACCEPTANCE_STATE:path.join(dataDir,'acceptance-state.json')},deadline:75000});
        const report=JSON.parse(result.stdout.trim().split('\n').at(-1));assert.equal(report.ok,true);
        checks.push(...report.checks);
      });
    }else{
      await ctx.check('CLI executable mode and whoami after fresh mount',async()=>{const stat=await lstat('packages/cli/bin/crew.js');assert.ok(stat.mode&0o111);const result=await ctx.cli(['whoami']);assert.equal(result.user.id,ids.clients.owner.user.id);});
      const module=await import(new URL('./checks/work.mjs',import.meta.url));await module.remount(ctx);
    }
  }else if(mode==='audit'){
    const census=await maintainedCensus();
    checks.push({name:'Complete maintained-file identity census',ok:true,...census});
    const {countProject,isProductionPath}=await import('./count-loc.mjs');
    const source=await readFile('scripts/count-loc.mjs');
    assert.equal(createHash('sha256').update(source).digest('hex'),'f73b6acb7d073e90631936ad62be8705a9c2a2f93c7e2097e7ca4f5c062f12ab');
    checks.push({name:'Frozen counter hash',ok:true});
    const count=await countProject(process.cwd());assert.ok(count.total>=10000,'At least 10000 production LOC');
    const largest=[];
    for(const file of count.files){const content=await readFile(file.path,'utf8');const lines=content.split('\n').length-(content.endsWith('\n')?1:0);assert.ok(lines<=999,`${file.path}: ${lines} physical lines`);largest.push({...file,physicalLines:lines});}
    checks.push({name:'Production census, scope and file-size ceiling',ok:true,total:count.total,packages:count.packages,largest:largest.sort((a,b)=>b.prod-a.prod).slice(0,15)});
    for(const name of ['README.md','docs/api.md','docs/architecture.md','docs/api-people.md','docs/api-work.md','docs/api-insight.md'])await access(name);
    checks.push({name:'Required operational and lane documentation',ok:true});
    for(const lane of ['people','work','insight'])await(await import(new URL(`./checks/${lane}.mjs`,import.meta.url))).audit({checks});
    const meta=JSON.parse(await readFile('packages/web/dist/meta.json','utf8'));
    assert.ok(!Object.keys(meta.inputs).some(name=>/devtools|test-utils|preact\/debug|\/test\//.test(name)));
    assert.ok(Object.values(meta.outputs).every(output=>!(output.imports??[]).some(item=>item.external)),'Browser bundle contains unresolved external imports');
    checks.push({name:'Production browser bundle',ok:true});
  }else if(mode==='closed'){
    for(const entry of await load('owned-processes.json',[])){let live=false;try{process.kill(entry.pid,0);live=true;}catch{}assert.equal(live,false,`Owned ${entry.kind} ${entry.pid} remains`);}
    const live=[];
    for(const name of await readdir('/proc')){
      if(!/^\d+$/.test(name))continue;
      let command;
      try{command=await readFile('/proc/'+name+'/cmdline','utf8');}
      catch(error){if(error.code==='ENOENT'||error.code==='ESRCH')continue;throw error;}
      if(/chromium|chromedriver|chrome_crashpad|scripts\/browser-smoke\.py|packages\/server\/src\/index\.js/.test(command))live.push({pid:Number(name),kind:command.includes('packages/server/src/index.js')?'server':'browser'});
    }
    assert.equal(live.length,0,'Owned application processes remain: '+JSON.stringify(live));
    checks.push({name:'No retained or live application/browser processes in selected Sandbox',ok:true});
  }else throw new Error('Expected smoke, restart, browser, remount, audit or closed');
}catch(cause){error=cause;checks.push({name:'Mode completion',ok:false,error:cause.message});}
finally{if(server){try{await server.stop();}catch(cause){error??=cause;checks.push({name:'Server clean shutdown',ok:false,error:cause.message});}const logs=server.logs();if(error)console.error(JSON.stringify({serverLogs:logs}));}}
const result={mode,checks,pass:checks.filter(c=>c.ok).length,fail:checks.filter(c=>!c.ok).length,ok:!error};
console.log(JSON.stringify(result));
if(error)process.exitCode=1;

import {readdir,readFile,lstat} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import path from 'node:path';

const excluded = new Set(['node_modules','dist','data','coverage','.git','.cache','__pycache__']);
export async function maintainedCensus(root=process.cwd()) {
  const files=[];
  async function visit(relative='') {
    const directory=path.join(root,relative);
    const entries=(await readdir(directory,{withFileTypes:true})).sort((a,b)=>a.name.localeCompare(b.name,'en'));
    for(const entry of entries) {
      if(excluded.has(entry.name)||entry.name.endsWith('.log')||entry.name.endsWith('.pyc'))continue;
      const name=relative?relative+'/'+entry.name:entry.name;
      if(entry.isSymbolicLink())throw new Error('Maintained file census refuses symlink: '+name);
      if(entry.isDirectory())await visit(name);
      else if(entry.isFile()) {
        const file=path.join(root,name);
        const [bytes,stat]=await Promise.all([readFile(file),lstat(file)]);
        files.push({path:name,bytes:bytes.length,sha256:createHash('sha256').update(bytes).digest('hex'),mode:stat.mode&0o777});
      } else throw new Error('Unsupported maintained file type: '+name);
    }
  }
  await visit();
  files.sort((a,b)=>a.path<b.path?-1:a.path>b.path?1:0);
  return {scope:'All maintained regular files; excludes dependencies, generated bundle, runtime data, coverage, Git, caches and logs',
    fileCount:files.length,bytes:files.reduce((sum,file)=>sum+file.bytes,0),files};
}
